#!/usr/bin/env python3
"""Recompute deterministic ground truth for CSX-317_Q2."""

from __future__ import annotations

import csv
import html
import json
import re
from datetime import date
from pathlib import Path
from typing import Any


TASK_ID = "CSX-317_Q2"
PACKAGE_ID = "CSX-317"
TARGET_FAMILY = "palcacocha_15min_route_threshold_proof"

REPORT_PATH = "data/event_reports/event_reports_001_Locked_package_evidence_report.html"
ANCHOR_PATH = "data/event_reports/event_reports_004_Locked_event_anchor_Lake_Palcacocha_GLOF_Huaraz_flood.json"
WEATHER_PATH = "data/physical_hazard/physical_hazard_001_Open-Meteo_archive_point_sample.json"
IMAGE_PATH = "data/remote_sensing/remote_sensing_001_pre.jpg"
EXPOSURE_PATH = "data/exposure_impact/exposure_impact_001_Overpass_small_critical-amenity_sample.json"


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8", errors="replace"))


def read_text(root: Path, rel_path: str) -> str:
    return (root / rel_path).read_text(encoding="utf-8", errors="replace")


def strip_html(raw_html: str) -> str:
    text = re.sub(r"(?is)<script\b.*?</script>|<style\b.*?</style>", " ", raw_html)
    text = re.sub(r"(?s)<[^>]+>", " ", text)
    text = html.unescape(text)
    text = text.replace("\u2019", "'").replace("\u201c", '"').replace("\u201d", '"')
    text = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def first_int(pattern: str, text: str) -> int:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return int(match.group(1).replace(",", ""))


def date_from_iso(value: str) -> date:
    year, month, day = (int(part) for part in value.split("-"))
    return date(year, month, day)


def file_row(root: Path, rel_path: str) -> dict[str, str]:
    with (root / "metadata/files.csv").open(newline="", encoding="utf-8") as handle:
        for row in csv.DictReader(handle):
            if row["relative_path"] == rel_path:
                return row
    raise ValueError(f"Missing file manifest row for {rel_path}")


def snapshot_date(row: dict[str, str]) -> str:
    match = re.search(r"(?:[?&]|&amp;)TIME=([0-9]{4}-[0-9]{2}-[0-9]{2})", row["url"])
    if not match:
        raise ValueError("Snapshot date not found in image URL")
    return match.group(1)


def amenity_count(exposure: dict[str, Any]) -> int:
    return len(exposure.get("elements", []))


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer form",
                "points": 4,
                "description": "Returns compact JSON with the requested fields and recoverable numeric values.",
            },
            {
                "name": "Route threshold",
                "points": 4,
                "description": "Computes 15 travel minutes and rapid_index = 2.0, then marks rapid_route true.",
            },
            {
                "name": "Rainfall threshold",
                "points": 3,
                "description": "Computes rain_ratio = 0.0 from the absence of a report-supported rainfall trigger and marks rainfall_control false.",
            },
            {
                "name": "Snapshot timing",
                "points": 3,
                "description": "Computes image_lag_years = 58.2 and marks event_window_footprint false.",
            },
            {
                "name": "Severity ratio",
                "points": 2,
                "description": "Computes fatality_city_ratio = 0.1167 from 7000 / 60000.",
            },
            {
                "name": "Final label",
                "points": 2,
                "description": "Uses rapid_ice_entry_glof_route or an equivalent short route label tied to the checks.",
            },
            {
                "name": "Failed-threshold rejection",
                "points": 1,
                "description": "Rejects one alternative directly from a failed computed threshold.",
            },
            {
                "name": "Overclaim control",
                "points": 1,
                "description": "Avoids adding new losses, mapped inundation, or facility failure beyond the checks.",
            },
        ],
    }


def source_files() -> list[str]:
    return [
        "metadata/event.json",
        "metadata/files.csv",
        REPORT_PATH,
        ANCHOR_PATH,
        IMAGE_PATH,
    ]


def build_gt() -> dict[str, Any]:
    root = package_root()
    event = read_json(root, "metadata/event.json")
    anchor = read_json(root, ANCHOR_PATH)
    report_text = strip_html(read_text(root, REPORT_PATH))

    event_date = anchor["temporal_window"]["start_date"]
    travel_minutes = first_int(r"take\s*([\d,]+)\s*minutes to reach the city", report_text)
    city_population = first_int(r"city of\s*([\d,]+)", report_text)
    historical_fatalities = first_int(r"killing\s*([\d,]+)\s*people", report_text)
    rainfall_trigger_reported = bool(re.search(r"\brain(?:fall|storm|storm-driven|trigger)", report_text, flags=re.IGNORECASE))
    image_date = snapshot_date(file_row(root, IMAGE_PATH))

    rapid_threshold_minutes = 30.0
    image_window_years = 1.0

    image_lag_years = round((date_from_iso(image_date) - date_from_iso(event_date)).days / 365.25, 1)
    metrics = {
        "travel_minutes": travel_minutes,
        "rapid_index": round(rapid_threshold_minutes / travel_minutes, 3),
        "rain_ratio": 1.0 if rainfall_trigger_reported else 0.0,
        "image_lag_years": image_lag_years,
        "fatality_city_ratio": round(historical_fatalities / city_population, 4),
    }
    pass_fail = {
        "rapid_route": metrics["rapid_index"] >= 1.0,
        "rainfall_control": metrics["rain_ratio"] >= 1.0,
        "event_window_footprint": metrics["image_lag_years"] <= image_window_years,
    }

    primary_gt = {
        "answer": "rapid_ice_entry_glof_route",
        "metrics": metrics,
        "pass_fail": pass_fail,
        "thresholds": {
            "rapid_index_min": 1.0,
            "rain_ratio_min": 1.0,
            "image_lag_years_max": image_window_years,
        },
        "tolerances": {
            "rapid_index": 0.001,
            "rain_ratio": 0.001,
            "image_lag_years": 0.1,
            "fatality_city_ratio": 0.0001,
        },
        "rejected_alternative": "rainfall_control_fails",
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "rubric": build_rubric(),
        "event": {
            "package_id": PACKAGE_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date": event_date,
            "location": anchor["spatial_window"]["location_text"],
        },
        "decision_rule": {
            "summary": "A route diagnosis passes when the 15-minute source-to-city time clears the rapid threshold while rainfall-control and event-window footprint tests fail.",
            "formulae": {
                "rapid_index": "30 / travel_minutes",
                "rain_ratio": "precipitation_mm / 50",
                "image_lag_years": "snapshot_date - event_date in years",
                "fatality_city_ratio": "historical_fatalities / city_population",
            },
        },
        "key_values": {
            "event_date": event_date,
        "snapshot_date": image_date,
            "snapshot_date_source": "metadata/files.csv URL TIME query for the contextual image",
            "rainfall_trigger_reported": rainfall_trigger_reported,
            "city_population": city_population,
            "historical_fatalities": historical_fatalities,
        },
        "numeric_tolerances": {
            key: {"target": value, "absolute_tolerance": primary_gt["tolerances"].get(key, 0)}
            for key, value in metrics.items()
            if key != "travel_minutes"
        }
        | {"travel_minutes": {"target": travel_minutes, "absolute_tolerance": 0}},
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": source_files(),
        },
    }


def main() -> None:
    out = Path(__file__).resolve().parent / "computed_gt.json"
    out.write_text(json.dumps(build_gt(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
